{
  "name": "oc-leakguard",
  "version": "0.13.0",
  "description": "Secret-exposure guard for OpenCode: blocks secret-file access and credential egress, redacts credentials from tool output. Detection delegated to betterleaks.",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "README.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "security",
    "secrets",
    "dlp",
    "betterleaks"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/calionauta/leakguard.git",
    "directory": "packages/oc-leakguard"
  },
  "peerDependencies": {
    "betterleaks": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "betterleaks": {
      "optional": true
    }
  }
}
